async function mkText(parent, str, x, y, size, weight, color, letterSpacing=0){
  const t = figma.createText();
  t.fontName = {family:'Inter', style:weight};
  t.characters = str; t.fontSize = size;
  t.fills = [{type:'SOLID', color:color || C.text}];
  t.x = x; t.y = y; t.letterSpacing = {value:letterSpacing, unit:'PIXELS'};
  parent.appendChild(t);
  return t;
}
function mkRect(parent, name, x, y, w, h, fill, r, strokeColor, sw){
  const rc = figma.createRectangle();
  rc.name = name; rc.x=x; rc.y=y; rc.resize(w,h);
  if(fill) rc.fills=[{type:'SOLID',color:fill}]; else rc.fills=[];
  if(r) rc.cornerRadius=r;
  if(strokeColor){ rc.strokes=[{type:'SOLID',color:strokeColor}]; rc.strokeWeight=sw||1; rc.strokeAlign='INSIDE'; }
  parent.appendChild(rc); return rc;
}

