// remove any existing 01_Home frames to avoid dupes
for(const h of [...ws.findAll(n=>n.name==='01_Home'&&n.type==='FRAME')]) h.remove();

const comps={};
for(const pg of figma.root.children){ for(const n of pg.findAll(n=>n.type==='COMPONENT')) if(!comps[n.name]) comps[n.name]=n; }
const ei=(nm)=>comps[nm]?comps[nm].createInstance():null;

