const black={r:0,g:0,b:0}, white={r:1,g:1,b:1}, gray={r:0.47,g:0.47,b:0.47}, gray6={r:0.94,g:0.94,b:0.94}, gray4={r:0.86,g:0.86,b:0.86};
function tk(parent,s,x,y,size,w,col,width){
  const t=figma.createText(); t.fontName={family:'Inter',style:w}; t.fontSize=size;
  t.fills=[{type:'SOLID',color:col}];
  t.characters=s; if(width){ t.textAutoResize='HEIGHT'; t.resize(width,size*1.4);}
  t.x=x; t.y=y; parent.appendChild(t); return t;
}
function fk(name,w,h,bg,r){ const f=figma.createFrame(); f.name=name; f.resize(w,h); f.fills=bg?[{type:'SOLID',color:bg}]:[]; if(r) f.cornerRadius=r; return f; }

