tk(hero,'Created to change everything for the better. For everyone',80,224,16,'Medium',white);
const hp=ei('Photo_Hero_Phone'); if(hp){hp.resize(140,300); hp.x=1120; hp.y=80; hero.appendChild(hp);}
// Shop Now button -> use Button not yet; add simple black-btn on white not here. Add shop now as link later. Provide button text
const shopBtn=fk('Shop Now',160,48,black,24); shopBtn.x=80; shopBtn.y=280; hero.appendChild(shopBtn);
tk(shopBtn,'Shop Now',32,12,16,'SemiBold',white);

// compact helpers for section title
const sectionTitle=(parent,txt,x,y)=>{
  const t=tk(parent,txt,x,y,30,'Bold',black);
  return t;
};

// CATEGORIES
const cat=fk('Categories',1440,300,white); cat.x=0; cat.y=496; H.appendChild(cat);
sectionTitle(cat,'Browse By Category',80,10);
// arrows
tk(cat,'‹',1290,10,40,'Bold',gray); tk(cat,'›',1330,10,40,'Bold',black);
const cats=[['Icon_Category_Phones','Phones'],['Icon_Category_Watches','Smart Watches'],['Icon_Category_Cameras','Cameras'],['Icon_Category_Headphones','Headphones'],['Icon_Category_Computers','Computers'],['Icon_Category_Gaming','Gaming']];
cats.forEach((c,i)=>{
  const tile=fk(c[1],196,150,white,12); tile.x=80+i*216; tile.y=70; cat.appendChild(tile);
  tile.strokes=[{type:'SOLID',color:gray4,strokeWeight:1}];
  const ic=ei(c[0]); if(ic){ic.resize(48,48); ic.x=(196-48)/2; ic.y=20; tile.appendChild(ic);}
  tk(tile,c[1],0,90,15,'Medium',black,196); tile.children[tile.children.length-1].textAlignHorizontal='CENTER';
});

return 'Home built with '+H.children.length+' sections';
}
return await run();

