function makeCard(photo, name, price, liked){
  const card=mk('Product Card',300,430,white);
  card.strokes=[{type:'SOLID',color:{r:0.92,g:0.92,b:0.92}}]; card.strokeWeight=1;
  const ph=ei(photo); card.appendChild(ph);
  if(ph){ ph.x=0; ph.y=0; ph.resize(300,250); }
  const heart=ei('Icon_Heart_Filled'); if(heart){ heart.resize(24,24); heart.x=258; heart.y=12; card.appendChild(heart);
     // liked fills red
     if(liked){ heart.fills=[{type:'SOLID',color:{r:0.9,g:0.2,b:0.25}}]; } }
  const nm=mt(name,15,'Medium',black); nm.x=16; nm.y=260; card.appendChild(nm);
  const pc=mt(price,17,'SemiBold',black); pc.x=16; pc.y=292; card.appendChild(pc);
  const btn=ei('Button'); btn.resize(180,44); btn.x=60; btn.y=340; card.appendChild(btn);
  const bt=btn.findOne(n=>n.type==='TEXT'); if(bt) bt.characters='Buy Now';
  return card;
}
